    const drought = stateFor(droughtScore, 2, 1); drought.reason = droughtScore ? "Soil moisture is below the crop-specific lower reference band." : "Soil moisture does not indicate drought stress in this illustrative input."; drought.action = "Check soil at root depth and confirm irrigation need before applying water.";
    const flood = stateFor(floodScore, 2, 1); flood.reason = floodScore ? "Rainfall or soil moisture is high enough to warrant drainage inspection." : "No waterlogging watch is indicated by the illustrative rainfall and soil moisture input."; flood.action = "Inspect low points and field drains after heavy rainfall.";
    const risks = { disease, pest, nutrient, irrigation, heat, drought, flood };
