  function renderAlerts() { const profile = state.workspace.profile; const assessment = buildAssessment(profile); const alerts = assessmentAlerts(profile, assessment); const open = alerts.filter((item) => item.status === "open"); text("#openAlertCount", open.length); text("#resolvedAlertCount", (state.workspace.alerts || []).filter((item) => item.status === "resolved").length); const list = $("#alertsList"); if (!list) return; const visible = state.alertFilter === "all" ? [...alerts, ...(state.workspace.alerts || []).filter((item) => item.status === "resolved")] : state.alertFilter === "resolved" ? (state.workspace.alerts || []).filter((item) => item.status === "resolved") : open; list.innerHTML = visible.length ? visible.map(alertRecord).join("") : `<div class="panel empty-state"><strong>${state.alertFilter === "resolved" ? "No resolved alerts yet" : "No open alerts"}</strong><span>Live alerts remain integration-ready and are never invented as diagnoses.</span></div>`; }
  function alertRecord(item) { const resolved = item.status === "resolved"; return `<article class="alert-record"><span class="alert-record-marker ${escapeHtml(item.level || "warning")}"></span><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.reason || item.desc)}</p><div class="alert-meta"><span>${escapeHtml(item.time || "Illustrative input")}</span><span>${escapeHtml(item.field || "Field not set")}</span><span>${escapeHtml(item.crop || "Crop not set")}</span><span>${escapeHtml(item.riskType || "field signal")}</span><span class="pill ${resolved ? "pill-green" : item.level === "danger" ? "pill-rose" : "pill-amber"}">${resolved ? "Resolved" : item.demo ? "Review locally" : "Open"}</span></div><small class="alert-action-line"><b>Recommended action:</b> ${escapeHtml(item.recommendedAction || "Inspect locally")}</small></div><div class="alert-actions"><small>${resolved ? `Resolved ${formatDate(item.resolvedAt)}` : "Action required"}</small>${resolved ? "" : `<button class="btn btn-secondary resolve-alert" data-alert-id="${escapeHtml(item.id)}" type="button">Mark reviewed</button>`}</div></article>`; }
